
// src/components/Chatbot.js
import React, { useState, useRef } from "react";
import ScrollToBottom from "react-scroll-to-bottom";
import { predictCrime } from "../api/chatbotApi";

export default function Chatbot() {
  const [messages, setMessages] = useState([]); // { from: 'user'|'bot', text, meta }
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const inputRef = useRef();

  const sendMessage = async () => {
    const text = input.trim();
    if (!text) return;
    // show user message
    setMessages((m) => [...m, { from: "user", text }]);
    setInput("");
    inputRef.current.focus();

    // call backend
    setLoading(true);
    const resp = await predictCrime(text);
    setLoading(false);

    if (resp && resp.error) {
      setMessages((m) => [...m, { from: "bot", text: "Sorry — server error. Please try again later." }]);
    } else {
      // expect { crime_type, guidance }
      const crime = resp.crime_type || "unknown";
      const guidance = resp.guidance || "Could not determine guidance. Please provide more details.";
      setMessages((m) => [...m, {
        from: "bot",
        text: guidance,
        meta: { detected: crime }
      }]);
    }
  };

  const onKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  return (
    <div className="chat-container">
      <div className="chat-left">
        <div className="chatbox">
          <ScrollToBottom className="messages">
            {messages.length === 0 && (
              <div className="welcome">
                <p>Hello — I'm CCVA. Describe your situation and I'll help you identify the type of cybercrime and what to do next.</p>
              </div>
            )}
            {messages.map((m, idx) => (
              <div key={idx} className={`message ${m.from}`}>
                <div className="bubble">
                  <div className="text">{m.text}</div>
                  {m.meta?.detected && (
                    <div className="detected">Detected: <strong>{m.meta.detected}</strong></div>
                  )}
                </div>
              </div>
            ))}
            {loading && (
              <div className="message bot">
                <div className="bubble">Processing... ⏳</div>
              </div>
            )}
          </ScrollToBottom>
        </div>

        <div className="input-area">
          <textarea
            ref={inputRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={onKeyDown}
            placeholder="Describe what happened (e.g. 'I got an email asking for my OTP')"
            rows={2}
          />
          <button onClick={sendMessage} className="send-btn" disabled={loading}>Send</button>
        </div>
      </div>

      <div className="chat-right">
        <section className="detector-info">
          <h3>Detected Crime</h3>
          <p>After you send a message, CCVA will detect the most likely crime type and show step-by-step guidance.</p>
        </section>

        <section className="quick-actions">
          <h3>Quick Report Links</h3>
          <ul>
            <li><a href="https://www.cybercrime.gov.in/" target="_blank" rel="noreferrer">National Cyber Crime Portal (India)</a></li>
            <li><a href="https://phishing.org/" target="_blank" rel="noreferrer">Report Phishing</a></li>
            <li><a href="https://www.ic3.gov/" target="_blank" rel="noreferrer">Report Financial Fraud (IC3)</a></li>
          </ul>
        </section>

        <section className="tips">
          <h3>Safety Tips</h3>
          <ul>
            <li>Don't share OTPs, passwords or personal documents</li>
            <li>Take screenshots and preserve evidence</li>
            <li>Disconnect affected devices from the internet</li>
          </ul>
        </section>
      </div>
    </div>
  );
}
