
// src/api/chatbotApi.js
import axios from "axios";

const API_BASE = process.env.REACT_APP_API_BASE || "http://127.0.0.1:5000";

export async function predictCrime(message) {
  try {
    const res = await axios.post(`${API_BASE}/api/chatbot/predict`, { message }, {
      headers: { "Content-Type": "application/json" }
    });
    return res.data; // expects { crime_type, guidance } or { error: ... }
  } catch (err) {
    console.error("API error:", err);
    return { error: "Server not responding. Try again later." };
  }
}
