
// src/components/AwarenessSection.js
import React from "react";

export default function AwarenessSection() {
  return (
    <section className="awareness">
      <h2>Awareness: Learn about common cybercrimes</h2>
      <div className="cards">
        <div className="card"><h4>Phishing</h4><p>Emails or messages asking for your credentials or money.</p></div>
        <div className="card"><h4>Ransomware</h4><p>Files locked and ransom demanded — do not pay; seek help.</p></div>
        <div className="card"><h4>Identity Theft</h4><p>Someone using your identity to open accounts or transactions.</p></div>
      </div>
    </section>
  );
}
